+                """;
+        assertEquals(400, post("/reservations", noIdentification).statusCode());
+
+        String twoIdentifications = """
+                {"roomNumber": 201, "guestName": "Guest", "guestEmail": "guest@example.com",
+                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Company",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 1, "ratePlan": "STANDARD"}
