    70	    private static String buildIndividualReceipt(Reservation reservation, Room room) {
    71	        StringBuilder text = new StringBuilder();
    72	        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
    73	        text.append("Hóspede: ").append(reservation.guest().name())
    74	                .append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
    75	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    76	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
    77	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
    78	                .append(" | ").append(reservation.price().nights())
    79	                .append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
    80	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
    81	        if (reservation.price().discount().signum() > 0) {
    82	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
    83	        }
    84	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
    85	        return text.toString();
    86	    }
    87	
    88	    private static String buildCompanyInvoice(Reservation reservation, Room room) {
    89	        StringBuilder text = new StringBuilder();
    90	        BigDecimal iss = PriceCalculator.cents(reservation.price().total().multiply(new BigDecimal("0.05")));
    91	        text.append("Fatura de hospedagem nº ").append(reservation.id()).append('\n');
    92	        text.append("Empresa: ").append(reservation.guest().companyName())
    93	                .append(" (CNPJ ").append(reservation.guest().companyCnpj()).append(")\n");
    94	        text.append("Hóspede: ").append(reservation.guest().name()).append('\n');
    95	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    96	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
    97	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
    98	                .append(" | ").append(reservation.price().nights())
    99	                .append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
   100	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
   101	        if (reservation.price().discount().signum() > 0) {
   102	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
   103	        }
   104	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
   105	        text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
